<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { convertFileSrc } from '@tauri-apps/api/core'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowDown, ArrowUp, Camera, Delete, Edit, Hide, Plus, UserFilled, View } from '@element-plus/icons-vue'
import AppCard from '../../components/common/AppCard.vue'
import EmptyState from '../../components/common/EmptyState.vue'
import PageHeader from '../../components/common/PageHeader.vue'
import type { ProfileBasic, ProfileEntityTable, ProfileField, ProfileRecord } from '../../types/profile'
import { deleteProfileRecord, getBasicProfile, getEvaluation, getHobbies, listProfileRecords, moveProfileRecord, removeProfilePhoto, replaceProfilePhoto, saveBasicProfile, saveEvaluation, saveHobbies, saveProfileRecord } from '../../services/profileService'
import { isTauriRuntime } from '../../services/databaseService'

interface EntityConfig { key:string; title:string; empty:string; table:ProfileEntityTable; primary:string; fields:ProfileField[] }
const yesNo=['是','否'],ability=['优秀','良好','一般','较弱']
const basicFields:ProfileField[]=[
  {key:'name',label:'姓名',required:true},{key:'english_name',label:'英文名 / 姓名全拼'},{key:'gender',label:'性别',type:'select',options:['男','女']},{key:'birth_date',label:'出生日期',type:'date'},{key:'ethnicity',label:'民族'},
  {key:'political_status',label:'政治面貌',type:'select',options:['中共党员','中共预备党员','共青团员','群众','其他']},{key:'marital_status',label:'婚姻状况',type:'select',options:['未婚','已婚','其他']},{key:'health_status',label:'健康状况'},{key:'height',label:'身高'},{key:'weight',label:'体重'},
  {key:'current_residence',label:'现居住地',wide:true},{key:'household_location',label:'户口所在地',wide:true},{key:'native_place',label:'籍贯'},{key:'student_origin',label:'生源地'},{key:'household_type',label:'户口类型'},{key:'mailing_address',label:'通信地址',wide:true},
  {key:'phone',label:'手机'},{key:'email',label:'邮箱'},{key:'work_start_date',label:'参加工作时间'},{key:'current_industry',label:'目前行业'},{key:'specialties',label:'特长爱好',wide:true},{key:'student_leader',label:'是否学生干部',type:'select',options:yesNo},{key:'overseas_work',label:'海外工作经历',type:'select',options:['有','无']},{key:'disciplinary_record',label:'违法违纪情况',type:'select',options:['有','无']},
]
const entities:EntityConfig[]=[
  {key:'education',title:'教育经历',empty:'暂无教育经历',table:'education_experiences',primary:'school_name',fields:[{key:'school_name',label:'学校名称',required:true},{key:'start_date',label:'开始时间',type:'month'},{key:'end_date',label:'结束时间',type:'month'},{key:'is_current',label:'至今',type:'switch'},{key:'duration_years',label:'学制'},{key:'education_level',label:'学历'},{key:'degree',label:'学位'},{key:'degree_detail',label:'学位细分'},{key:'study_type',label:'学习形式'},{key:'admission_type',label:'招生方式'},{key:'college',label:'学院'},{key:'major',label:'专业'},{key:'major_category',label:'专业分类'},{key:'research_direction',label:'研究方向'},{key:'ranking',label:'专业排名'},{key:'is_top_up_degree',label:'是否专升本',type:'switch'},{key:'is_overseas',label:'是否海外学习',type:'switch'},{key:'position',label:'担任职务'},{key:'main_courses',label:'主修课程',type:'textarea',wide:true},{key:'failed_course_count',label:'挂科门数',type:'number'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'work',title:'工作 / 实习',empty:'暂无工作或实习经历',table:'work_experiences',primary:'company_name',fields:[{key:'company_name',label:'企业名称',required:true},{key:'company_type',label:'单位性质'},{key:'industry',label:'所属行业'},{key:'work_type',label:'工作性质'},{key:'position_name',label:'职位名称'},{key:'start_date',label:'开始时间',type:'month'},{key:'end_date',label:'结束时间',type:'month'},{key:'is_current',label:'至今',type:'switch'},{key:'region',label:'工作地区'},{key:'monthly_salary',label:'税前月薪'},{key:'salary_unit',label:'薪资单位'},{key:'subordinate_count',label:'下属人数',type:'number'},{key:'is_overseas',label:'是否海外工作',type:'switch'},{key:'responsibilities',label:'工作职责',type:'textarea',wide:true},{key:'reference_name',label:'证明人'},{key:'reference_position',label:'证明人单位及职务'},{key:'reference_phone',label:'证明人联系电话'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'projects',title:'项目经历',empty:'暂无项目经历',table:'project_experiences',primary:'project_name',fields:[{key:'project_name',label:'项目名称',required:true},{key:'start_date',label:'开始时间',type:'month'},{key:'end_date',label:'结束时间',type:'month'},{key:'is_current',label:'至今',type:'switch'},{key:'role',label:'项目角色'},{key:'organization',label:'所在单位'},{key:'team_size',label:'团队规模',type:'number'},{key:'description',label:'项目介绍',type:'textarea',wide:true},{key:'responsibilities',label:'项目职责',type:'textarea',wide:true},{key:'achievements',label:'项目成果',type:'textarea',wide:true},{key:'tech_stack',label:'技术栈',wide:true},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'academic',title:'学术成果',empty:'暂无学术成果',table:'academic_achievements',primary:'achievement_name',fields:[{key:'achievement_name',label:'成果名称 / 论文名称',required:true,wide:true},{key:'achievement_type',label:'成果类型',type:'select',options:['期刊论文','会议论文','专利','软件著作权','其他']},{key:'author_role',label:'作者身份',type:'select',options:['第一作者','共同第一作者','第二作者','第三作者','通讯作者','其他']},{key:'venue',label:'期刊 / 会议名称'},{key:'status',label:'状态',type:'select',options:['准备投稿','已投稿','审稿中','已录用','已发表']},{key:'accepted_date',label:'录用时间',type:'date'},{key:'published_date',label:'发表时间',type:'date'},{key:'research_field',label:'研究方向'},{key:'doi',label:'DOI'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'certificates',title:'资格证书',empty:'暂无资格证书',table:'certificates',primary:'certificate_name',fields:[{key:'certificate_name',label:'证书名称',required:true},{key:'obtained_date',label:'获得时间',type:'month'},{key:'level',label:'等级'},{key:'score',label:'成绩'},{key:'certificate_number',label:'证书编号'},{key:'valid_until',label:'有效期'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'languages',title:'语言能力',empty:'暂无语言能力记录',table:'language_abilities',primary:'language',fields:[{key:'language',label:'语言',required:true},{key:'level',label:'等级'},{key:'score',label:'成绩'},{key:'speaking_ability',label:'听说能力',type:'select',options:ability},{key:'reading_ability',label:'读写能力',type:'select',options:ability},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'honors',title:'荣誉奖励',empty:'暂无荣誉奖励',table:'honors',primary:'honor_name',fields:[{key:'honor_name',label:'奖励名称',required:true},{key:'obtained_date',label:'获得时间',type:'month'},{key:'honor_level',label:'奖励级别',type:'select',options:['国家级','省部级 / 省区级','市级','学校级','学院级','其他']},{key:'award_grade',label:'获奖等级',type:'select',options:['特等奖','一等奖','二等奖','三等奖','优秀','其他']},{key:'issuer',label:'颁发机构'},{key:'description',label:'描述',type:'textarea',wide:true},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'family',title:'家庭成员',empty:'暂无家庭成员',table:'family_members',primary:'name',fields:[{key:'name',label:'姓名',required:true},{key:'relationship',label:'与本人关系'},{key:'organization',label:'工作单位'},{key:'position',label:'职务'},{key:'phone',label:'联系电话'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
  {key:'emergency',title:'紧急联系人',empty:'暂无紧急联系人',table:'emergency_contacts',primary:'name',fields:[{key:'name',label:'姓名',required:true},{key:'relationship',label:'与本人关系'},{key:'phone',label:'联系电话'},{key:'organization',label:'工作单位'},{key:'remark',label:'备注',type:'textarea',wide:true}]},
]
const tabs=[{key:'basic',label:'基本信息'},...entities.map(item=>({key:item.key,label:item.title})),{key:'evaluation',label:'自我评价'},{key:'hobbies',label:'兴趣爱好'}]
const activeTab=ref('basic'),loading=ref(false),basic=reactive<ProfileBasic>({}),rows=reactive<Record<string,ProfileRecord[]>>({}),expanded=ref<number[]>([]),visiblePhones=ref<string[]>([])
const evaluation=ref(''),hobbyTags=ref<string[]>([]),hobbyDescription=ref(''),newHobby=ref('')
const drawerVisible=ref(false),drawerMode=ref<'basic'|'entity'>('basic'),editingId=ref<number>(),editingConfig=ref<EntityConfig>(),form=reactive<Record<string,any>>({}),initialForm=ref('')
const activeEntity=computed(()=>entities.find(item=>item.key===activeTab.value))
const completeness=computed(()=>Math.round(basicFields.filter(field=>String((basic as any)[field.key]??'').trim()).length/basicFields.length*100))
const photoUrl=computed(()=>basic.photo_path?convertFileSrc(basic.photo_path):'')

async function load(){if(!isTauriRuntime())return;loading.value=true;try{Object.assign(basic,await getBasicProfile());for(const config of entities)rows[config.key]=await listProfileRecords(config.table);evaluation.value=(await getEvaluation()).content||'';const hobbies=await getHobbies();hobbyTags.value=(hobbies.tags||'').split('\n').filter(Boolean);hobbyDescription.value=hobbies.description||''}catch(error){ElMessage.error(error instanceof Error?error.message:'读取个人资料失败')}finally{loading.value=false}}
function displayValue(field:ProfileField,value:any){if(field.type==='switch')return value?'是':'否';return value===null||value===undefined||value===''?'未填写':String(value)}
function maskPhone(value:any){const text=String(value??'');return text.length>=7?`${text.slice(0,3)}****${text.slice(-4)}`:(text||'未填写')}
function openBasic(){drawerMode.value='basic';editingId.value=basic.id;editingConfig.value=undefined;Object.keys(form).forEach(key=>delete form[key]);basicFields.forEach(field=>form[field.key]=(basic as any)[field.key]??(field.type==='switch'?false:''));initialForm.value=JSON.stringify(form);drawerVisible.value=true}
function openEntity(config:EntityConfig,row?:ProfileRecord){drawerMode.value='entity';editingConfig.value=config;editingId.value=row?.id;Object.keys(form).forEach(key=>delete form[key]);config.fields.forEach(field=>form[field.key]=row?.[field.key]??(field.type==='switch'?false:''));initialForm.value=JSON.stringify(form);drawerVisible.value=true}
async function saveDrawer(){const fields=drawerMode.value==='basic'?basicFields:editingConfig.value!.fields;const missing=fields.find(field=>field.required&&!String(form[field.key]??'').trim());if(missing){ElMessage.warning(`请填写${missing.label}`);return}if(drawerMode.value==='basic')await saveBasicProfile(form as ProfileBasic);else await saveProfileRecord(editingConfig.value!.table,form,editingId.value);ElMessage.success('保存成功');drawerVisible.value=false;await load()}
function closeDrawer(done:()=>void){if(JSON.stringify(form)===initialForm.value){done();return}ElMessageBox.confirm('当前修改尚未保存，确定要关闭吗？','未保存修改',{type:'warning',confirmButtonText:'确定关闭',cancelButtonText:'继续编辑'}).then(done).catch(()=>undefined)}
async function remove(config:EntityConfig,row:ProfileRecord){try{await ElMessageBox.confirm(`确定删除“${row[config.primary]??config.title}”吗？`,'删除记录',{type:'warning'})}catch{return}await deleteProfileRecord(config.table,row.id);ElMessage.success('删除成功');await load()}
async function move(config:EntityConfig,row:ProfileRecord,direction:-1|1){await moveProfileRecord(config.table,row.id,direction);await load()}
function toggleExpanded(id:number){expanded.value=expanded.value.includes(id)?expanded.value.filter(item=>item!==id):[...expanded.value,id]}
function phoneKey(table:ProfileEntityTable,id:number){return `${table}-${id}`}
function phoneVisible(table:ProfileEntityTable,id:number){return visiblePhones.value.includes(phoneKey(table,id))}
function togglePhone(table:ProfileEntityTable,id:number){const key=phoneKey(table,id);visiblePhones.value=visiblePhones.value.includes(key)?visiblePhones.value.filter(item=>item!==key):[...visiblePhones.value,key]}
async function changePhoto(){try{const path=await replaceProfilePhoto(basic.photo_path);if(path){ElMessage.success('照片已更新');await load()}}catch(error){ElMessage.error(error instanceof Error?error.message:'照片更新失败')}}
async function deletePhoto(){try{await ElMessageBox.confirm('确定删除个人照片吗？','删除照片',{type:'warning'})}catch{return}await removeProfilePhoto(basic.photo_path);ElMessage.success('照片已删除');await load()}
async function saveText(){await saveEvaluation(evaluation.value);ElMessage.success('保存成功')}
function addHobby(){const value=newHobby.value.trim();if(value&&!hobbyTags.value.includes(value))hobbyTags.value.push(value);newHobby.value=''}
async function saveHobbyData(){addHobby();await saveHobbies(hobbyTags.value,hobbyDescription.value);ElMessage.success('保存成功')}
onMounted(load)
</script>

<template><div v-loading="loading" class="profile-page"><PageHeader title="我的资料" subtitle="集中管理个人求职信息，方便填写招聘系统和维护个人资料"><span class="completion">资料完整度 {{ completeness }}%</span><el-button :icon="Edit" type="primary" @click="openBasic">编辑资料</el-button></PageHeader><el-alert v-if="!isTauriRuntime()" title="当前是界面预览；个人资料仅保存在 Windows 客户端本机。" type="info" show-icon :closable="false"/>
  <AppCard class="tabs-card"><el-tabs v-model="activeTab"><el-tab-pane v-for="tab in tabs" :key="tab.key" :label="tab.label" :name="tab.key"/></el-tabs></AppCard>
  <AppCard v-if="activeTab==='basic'" class="content-card basic-card"><div class="section-head"><div><h2>基本信息</h2><p>个人身份、联系方式与求职常用信息</p></div><el-button :icon="Edit" @click="openBasic">编辑</el-button></div><div class="basic-layout"><div class="photo-panel"><div class="photo-frame"><img v-if="photoUrl" :src="photoUrl" alt="个人照片"/><el-icon v-else><UserFilled/></el-icon></div><el-button :icon="Camera" link type="primary" @click="changePhoto">{{ basic.photo_path?'更换照片':'上传照片' }}</el-button><el-button v-if="basic.photo_path" :icon="Delete" link type="danger" @click="deletePhoto">删除</el-button><small>JPG、JPEG 或 PNG</small></div><dl class="info-grid"><div v-for="field in basicFields" :key="field.key" :class="{wide:field.wide}"><dt>{{ field.label }}</dt><dd>{{ displayValue(field,(basic as any)[field.key]) }}</dd></div></dl></div></AppCard>
  <AppCard v-else-if="activeEntity" class="content-card"><div class="section-head"><div><h2>{{ activeEntity.title }}</h2><p>共 {{ rows[activeEntity.key]?.length||0 }} 条记录，可编辑、排序和展开查看</p></div><el-button :icon="Plus" type="primary" @click="openEntity(activeEntity)">新增{{ activeEntity.title }}</el-button></div><div v-if="rows[activeEntity.key]?.length" class="record-list"><article v-for="(row,index) in rows[activeEntity.key]" :key="row.id" class="record-item"><div class="record-main"><div><strong>{{ row[activeEntity.primary] }}</strong><p>{{ row.start_date||row.obtained_date||row.accepted_date||'' }}<template v-if="row.end_date"> ～ {{ row.is_current?'至今':row.end_date }}</template><template v-if="row.position_name||row.role||row.major"> · {{ row.position_name||row.role||row.major }}</template></p><small v-if="activeEntity.key==='projects'">{{ row.description||'暂无项目介绍' }}</small></div><div class="record-actions"><el-button :icon="ArrowUp" :disabled="index===0" title="上移" @click="move(activeEntity,row,-1)"/><el-button :icon="ArrowDown" :disabled="index===rows[activeEntity.key].length-1" title="下移" @click="move(activeEntity,row,1)"/><el-button :icon="Edit" title="编辑" @click="openEntity(activeEntity,row)"/><el-button :icon="Delete" type="danger" title="删除" @click="remove(activeEntity,row)"/><el-button link type="primary" @click="toggleExpanded(row.id)">{{ expanded.includes(row.id)?'收起详情':'展开详情' }}</el-button></div></div><dl v-show="expanded.includes(row.id)" class="detail-grid"><div v-for="field in activeEntity.fields" :key="field.key" :class="{wide:field.wide}"><dt>{{ field.label }}</dt><dd v-if="['phone','reference_phone'].includes(field.key)"><span>{{ phoneVisible(activeEntity.table,row.id)?displayValue(field,row[field.key]):maskPhone(row[field.key]) }}</span><el-button :icon="phoneVisible(activeEntity.table,row.id)?Hide:View" link @click="togglePhone(activeEntity.table,row.id)"/></dd><dd v-else>{{ displayValue(field,row[field.key]) }}</dd></div></dl></article></div><EmptyState v-else :title="activeEntity.empty" :description="`点击上方按钮添加${activeEntity.title}。`"><el-button :icon="Plus" type="primary" @click="openEntity(activeEntity)">添加{{ activeEntity.title }}</el-button></EmptyState></AppCard>
  <AppCard v-else-if="activeTab==='evaluation'" class="content-card"><div class="section-head"><div><h2>自我评价</h2><p>用于招聘系统中的个人总结</p></div><span>{{ evaluation.length }} 字</span></div><el-input v-model="evaluation" type="textarea" :rows="10" placeholder="填写自我评价"/><div class="save-row"><el-button type="primary" @click="saveText">保存</el-button></div></AppCard>
  <AppCard v-else class="content-card"><div class="section-head"><div><h2>兴趣爱好</h2><p>输入后按回车添加标签</p></div></div><div class="hobby-tags"><el-tag v-for="tag in hobbyTags" :key="tag" closable @close="hobbyTags=hobbyTags.filter(item=>item!==tag)">{{ tag }}</el-tag><el-input v-model="newHobby" placeholder="输入兴趣爱好并回车" @keyup.enter="addHobby"/></div><el-input v-model="hobbyDescription" type="textarea" :rows="6" placeholder="补充说明"/><div class="save-row"><el-button type="primary" @click="saveHobbyData">保存</el-button></div></AppCard>
  <el-drawer v-model="drawerVisible" :title="drawerMode==='basic'?'编辑基本信息':`${editingId?'编辑':'新增'}${editingConfig?.title||''}`" size="min(640px, 92vw)" :before-close="closeDrawer"><el-form label-position="top"><div class="form-grid"><el-form-item v-for="field in (drawerMode==='basic'?basicFields:editingConfig?.fields||[])" :key="field.key" :label="field.label" :required="field.required" :class="{wide:field.wide}"><el-input v-if="!field.type||field.type==='text'" v-model="form[field.key]"/><el-input v-else-if="field.type==='textarea'" v-model="form[field.key]" type="textarea" :rows="4"/><el-input-number v-else-if="field.type==='number'" v-model="form[field.key]" :min="0"/><el-date-picker v-else-if="field.type==='date'" v-model="form[field.key]" type="date" value-format="YYYY-MM-DD"/><el-date-picker v-else-if="field.type==='month'" v-model="form[field.key]" type="month" value-format="YYYY-MM"/><el-select v-else-if="field.type==='select'" v-model="form[field.key]" filterable allow-create clearable><el-option v-for="option in field.options" :key="option" :label="option" :value="option"/></el-select><el-switch v-else v-model="form[field.key]"/></el-form-item></div></el-form><template #footer><el-button @click="drawerVisible=false">取消</el-button><el-button type="primary" @click="saveDrawer">保存</el-button></template></el-drawer>
</div></template>

<style scoped lang="scss">.profile-page{display:grid;gap:16px}.completion{border-radius:999px;padding:7px 11px;color:#6254d9;background:#f0edff;font-size:12px;font-weight:700}.tabs-card{padding:0 18px}.tabs-card :deep(.el-tabs__header){margin:0}.tabs-card :deep(.el-tabs__nav-wrap){overflow:auto}.tabs-card :deep(.el-tabs__nav-wrap::after){height:1px}.tabs-card :deep(.el-tabs__item.is-active){color:#6c5ce7}.tabs-card :deep(.el-tabs__active-bar){height:2px;background:#6c5ce7}.content-card{min-height:440px;padding:22px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.section-head h2{margin:0;color:var(--text-primary);font-size:18px}.section-head p{margin:5px 0 0;color:var(--text-secondary);font-size:13px}.section-head>span{color:var(--text-secondary)}.basic-layout{display:grid;grid-template-columns:150px minmax(0,1fr);gap:28px}.photo-panel{display:flex;align-items:center;flex-direction:column;gap:5px}.photo-frame{display:grid;width:112px;aspect-ratio:3/4;place-items:center;overflow:hidden;border:1px solid var(--border-color);border-radius:8px;background:#f7f5ff}.photo-frame img{width:100%;height:100%;object-fit:cover}.photo-frame .el-icon{color:#8b7cf6;font-size:42px}.photo-panel small{color:var(--text-tertiary)}.info-grid,.detail-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin:0}.info-grid div,.detail-grid div{min-width:0}.info-grid .wide,.detail-grid .wide{grid-column:span 2}.info-grid dt,.detail-grid dt{margin-bottom:6px;color:var(--text-tertiary);font-size:12px}.info-grid dd,.detail-grid dd{margin:0;overflow-wrap:anywhere;color:var(--text-primary);line-height:1.65}.record-list{display:grid;gap:10px}.record-item{border:1px solid var(--border-color);border-radius:8px;background:var(--bg-card)}.record-main{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 18px}.record-main strong{font-size:15px}.record-main p{margin:6px 0 0;color:var(--text-secondar